import logging
from .paragon import ParagonxAPI
import os
import time
from taf.transport.ssh import ssh
from.ssh_cmd import create_dir,copy_file_to_remote_path,download_file_from_remote_path

ssh = ssh()
log = logging.getLogger(__name__)


class ParagonWrapper(object):

    def __init__(self):
        self.p = None
        self.restore_flag = False
        self.restore_filename = None
        self.home_directory = "C:\Calnex_Automation"
        self.inst_address = None
        self.gui_address = None
        self.gui_user = None
        self.gui_password = None
        self.gui_port = 9000
        self.inst_port = 9990
        self.ssh_alias = 'default_para'
        self.rc = 1
        self.cat_settings_filename = None

    def _setup_init(self):
        ssh.send_command('rmdir /S /Q  {}\\'.format(self.home_directory), connection=self.ssh_alias)
        create_dir(ssh_alias=self.ssh_alias, path=os.path.join(self.home_directory, 'traces').replace("/", "\\"))

    def _setup_down(self):
        pass

    def connect(self, inst_address,
                gui_address,
                gui_user='admin',
                gui_password='5gtester',
                gui_port=None,
                inst_port=None,
                rc=None,
                ssh_alias=None,
                restore_flag=True,
                home_directory=None):

        """
        Makes a connection to the specified GUI and instrument.
        :param home_directory: Calnex Home directory where all data will store in remote PC
        :param ssh_alias: alias name for SSH connection to calnex remote PC
        :param inst_address:This is the IP address of the Paragon instrument.
        :param gui_address: This specifies the IP address of the PC that is hosting the GUI.
        :param gui_user: This specifies the user name of the PC that is hosting the GUI.
        :param gui_password: This specifies the password of the PC that is hosting the GUI.
        :param gui_port: This specifies the remote control TCP Port used by the Paragon client application; 
                            if this parameter is not specified then port 9000 is assumed.
        :param inst_port: This specifies the TCP Port on the Paragon instrument;
                            if this parameter is not specified then port 9990 is assumed.
        :param rc: This parameter specifies remote control on or not.Default: 1
        :param restore_flag: This specifies Saving current setup settings to configuration file before connect 
                              to Paragon instrument; and load saved setup file once testing is completed. 
                              default value is True.
        :rtype: Null
        
        """
        self.inst_address = inst_address
        self.gui_address = gui_address
        if gui_port is not None:
            self.gui_port = gui_port
        if inst_port is not None:
            self.inst_port = inst_port
        self.gui_password = gui_password
        self.gui_user = gui_user
        if rc is not None:
            self.rc = rc
        if ssh_alias is None:
            self.ssh_alias = self.default_alias
        if home_directory is not None:
            self.home_directory = home_directory
        self.ssh_alias = ssh_alias
        self.p = ParagonxAPI(inst_address, gui_address, gui_port, inst_port, rc)
        ssh.connect_to(gui_address, gui_user, gui_password, alias=self.ssh_alias)
        self._setup_init()
        self.p.connect()
        if restore_flag:
            self.restore_filename = os.path.join(self.home_directory, "config_bak.cst").replace("/", "\\")
            self.store_setup_file(self.restore_filename)
            self.restore_flag = restore_flag

    def disconnect(self):
        """
        Disconnnects the currently connected instrument.
        """
        if self.restore_flag and self.restore_filename is not None:
            self.load_setup_file(self.restore_filename)
        self.p.disconnect()
        self._setup_down()
        ssh.disconnect(connection=self.ssh_alias)

    def load_setup_file(self, filename):
        """
        Recalls the instrument settings from the file passed in using the filename
        :param filename: Path and filename for a file on the local PC's
                            file system
        """
        if not filename.endswith(".cst"):
            raise Exception("Not a valid filename...{}. Valid filename extension: .cst".format(filename))
        log.info('Recall previous setup settings from configuration file ... ({})'.format(filename))
        self.p.instrumentdisconnect()
        try:
            self.p.recall(filename)
        except Exception as e:
            error_msg = "Execution error"
            if error_msg in e.message:
                log.info(e.message)
            else:
                raise Exception(e.message)
        self.p.instrumentconnect()

    def store_setup_file(self, filename=None):
        """
        stores the instrument settings to the file passed in using the filename
        :param filename: Path and filename for a file on the local PC's
                            file system.
        """
        if filename is None:
            filename = os.path.join(self.home_directory, "save_instrument_settings.cst").replace("/", "\\")
        if not filename.endswith(".cst"):
            raise Exception("Not a valid filename...{}. Valid filename extension: .cst".format(filename))
        log.info('Saving current setup settings to configuration file ... ({})'.format(filename))
        self.p.store(filename)
        time.sleep(3)
        return filename

    def restore_setup_file(self):
        """
        stores the instrument settings, if self.restore_flag == TRUE and self.restore_filename != None
        """
        if self.restore_flag and self.restore_filename is not None:
            self.load_setup_file(self.restore_filename)

    def load_setup_file_from_remote_path(self, filename):
        """
        stores the instrument settings to the file passed in using the remote filename path
        :param filename: path and filename for a file from remote PC's
                            file system.
        """
        if not filename.endswith(".cst"):
            raise Exception("Not a valid filename...{}. Valid filename extension: .cst".format(filename))
        remote_path = os.path.join(self.home_directory, filename.split('/')[-1]).replace("/", "\\")
        copy_file_to_remote_path(self.ssh_alias, filename, remote_path)
        self.load_setup_file(remote_path)
        return remote_path

    def get_value(self, arg_str):

        """
        Query an instrument setting. Most of the instrument's settings are read
        using by this command. (Refer to the remote control manual for the complete list)
        :param arg_str: parameter name to get value/status in string
        Ex:InstrumentStatus Interface SyncELock Detected
        :return: 
        :rtype: basestring
        """
        return self.p.paragonget(arg_str)

    def set_value(self, arg_str, value=None):
        """
        Set an instrument setting. Most of the instrument's settings are controlled
        using by this command. (Refer to the remote control manual for the complete list)
        :param arg_str: parameter name to set value/status in string
        :param value: parameter value to set value/status in string
        :return: Null, 
        """
        self.p.paragonset(arg_str, value)

    def get_values(self, param_list):

        """
        Query an instrument settings. Most of the instrument's settings are read
        using by this command. (Refer to the remote control manual for the complete list)
        :param param_list: parameters name to get value/status in List
        Ex:InstrumentStatus Interface SyncELock Detected
        :return: 
        :rtype: dict
        """
        value_dict = {}
        for arg_str in param_list:
            value_dict[arg_str] = self.get_value(arg_str)
        return value_dict

    def set_values(self, params_dict):
        """
        Set an instrument settings. Most of the instrument's settings are controlled
        using by this command. (Refer to the remote control manual for the complete list)
        :param params_dict: Dictionary contains parameter name and value pair
        :return: Null, 
        """

        for key in params_dict:
            self.set_value(key, params_dict[key])

    def start_packet_capture(self):
        """
        Starts an ALL byte capture.
        :return: 
        """
        self.p.startpacketcapture()

    def start_timing_capture(self):
        """
        Starts timing capture.
        :return: 
        """
        self.p.starttimingcapture()

    def stop_capture(self):
        """
        Stops current capture.
        :return: 
        """
        self.p.stopcapture()

    def start_impairment(self):
        """
        Enables the impairment as configured in the settings
        :return: 
        """
        self.p.startimpairment()

    def stop_impairment(self):
        """
        Disables the impairment as configured in the settings.
        :return: 
        """
        self.p.stopimpairment()

    def start_tod_capture(self):
        """
        Starts Time of Day capture.
        :return: 
        """
        self.p.starttodcapture()

    def stop_tod_capture(self):
        """
        Stops Time Of Day capture.
        :return: 
        """
        self.p.stoptodcapture()

    def export_data(self, filename=None):
        """
        Saves the displayed captured data to a file.
        :param filename: required  Path and filename for a file on the local PC's
                          file system. filename must be suffixed with a
                          valid filename extension:
                         - ".csv"
                         - ".cpd"
                         - ".clxz"
                         if filename is None, filename = self.home_directory +time+ ".clxz"
        """
        if filename is None:
            filename = os.path.join(self.home_directory, "captured_data_"+str(time.time())+".clxz").replace("\\", "/")
        if not (filename.endswith(".clxz") or filename.endswith(".cpd") or filename.endswith(".csv")):
            raise Exception("Not a valid filename...{}. Valid filename extension: .csv, .cpd, .clxz".format(filename))
        log.info('Saves the displayed captured data to a file ... ({})'.format(filename))
        self.p.exportdata(filename)
        return filename

    def import_data(self, filename):
        """
        Loads the captured data from a file.
        :param filename: required  Path and filename for a file on the local PC's
                          file system. filename must be suffixed with a
                          valid filename extension:
                         - ".csv"
                         - ".cpd"
        """
        log.info('Loads the captured data from a file ... ({})'.format(filename))
        if not (filename.endswith(".cpd") or filename.endswith(".csv")):
            raise Exception("Not a valid filename...{}. Valid filename extension: .csv, .cpd".format(filename))
        self.p.importdata(filename)
        self.waitforcat()

    def import_impairmentdata(self, port, filename):
        """
        Loads the capture data for replay. It will load files specifically to replay.
        delay profiles against defined message types on defined ports.
        The loaded file will be replayed against incoming traffic on the given port.
        :param port:  required  The Ethernet port (1 or 2).
        :param filename: required  PPath to a capture file on the local PC's
                           file system.
        """
        log.info(
            'Loads the capture data for replay. It will load files specifically to replay ... ({})'.format(filename))
        self.p.importimpairmentdata(port, filename)
        self.waitforcat()

    def waitforcat(self):
        """
        Wait for the completion of the current CAT operation.
        """
        log.info('Wait for the completion of the current CAT operation.')
        self.p.waitforcat()

    def load_cat_settings(self, filename=None):
        """

        :param filename: The full file path and name (must have a .cps extension).
        """
        if filename is None:
            if self.cat_settings_filename is None:
                log.info('Failed to load CAT Settings. Empty FileName ... ({})'.format(filename))
                raise Exception('Failed to load CAT Settings. Empty FileName')
            else:
                filename = self.cat_settings_filename
        if not filename.endswith(".cps"):
            raise Exception("Not a valid filename...{}. Valid filename extension: .cps".format(filename))
        log.info('Recall previous CAT settings from configuration file ... ({})'.format(filename))
        self.set_value("Cat LoadSettings", filename)

    def save_cat_settings(self, filename=None):
        """

        :param filename: The full file path and name (must have a .cps extension).
        
        """
        if filename is None:
            self.cat_settings_filename = os.path.join(self.home_directory, "cat_settings.cps").replace("\\", "/")
            filename = self.cat_settings_filename
        else:
            self.cat_settings_filename = filename
        if not filename.endswith(".cps"):
            raise Exception("Not a valid filename...{}. Valid filename extension: .cps".format(filename))
        log.info('Saving current CAT settings to configuration file ... ({})'.format(filename))
        self.set_value("Cat SaveSettings", filename)
        return filename

    def load_cat_settings_from_remote_path(self, filename):
        if filename is None:
            raise Exception("Failed to load CAT Settings. Empty FileName")
        if not filename.endswith(".cps") or filename is None:
            raise Exception("Not a valid filename...{}. Valid filename extension: .cps".format(filename))
        remote_path = os.path.join(self.home_directory, filename.split('/')[-1]).replace("\\", "/")
        copy_file_to_remote_path(self.ssh_alias, filename, remote_path)
        self.load_cat_settings(remote_path)
        return remote_path
